  // ---- Live household context (optional, graceful if unavailable) ----
  function buildLiveContext() {
    const s = window.STATE;
    if (!s || typeof s !== "object") return null;
    try {
      const lines = [];
      const today = new Date();
      const in7 = new Date(today.getTime() + 7 * 86400000);

      if (Array.isArray(s.bills) && s.bills.length) {
        const unpaid = s.bills.filter((b) => {
          const key = today.toISOString().slice(0, 7);
          return !(b.paidPeriods && b.paidPeriods[key]);
        });
        lines.push(`Bills not yet marked paid this period: ${unpaid.map((b) => `${b.name} ($${b.amount}, due day ${b.dueDay})`).join("; ") || "none"}.`);
      }
      if (Array.isArray(s.assets) && s.assets.length) {
        const flagged = s.assets.filter((a) => a.needsAttention && a.needsAttention.flag);
        const notDone = s.assets.filter((a) => (a.items || []).some((i) => !i.checked));
        lines.push(`Household areas flagged for attention: ${flagged.map((a) => a.name).join(", ") || "none"}. Areas with unchecked items: ${notDone.map((a) => a.name).join(", ") || "none"}.`);
      }
      if (Array.isArray(s.groceries) && s.groceries.length) {
        const active = s.groceries.filter((g) => !g.used && !g.thrown);
        const expiringSoon = active.filter((g) => g.expirationDate && new Date(g.expirationDate) <= in7);
        lines.push(`Groceries expiring within 7 days: ${expiringSoon.map((g) => `${g.name} (exp ${g.expirationDate})`).join("; ") || "none"}.`);
      }
      if (Array.isArray(s.vehicles) && s.vehicles.length) {
        s.vehicles.forEach((v) => {
          const overdue = (v.tasks || []).filter((t) => t.dueDate && new Date(t.dueDate) < today);
          if (overdue.length) lines.push(`${v.name}: overdue maintenance — ${overdue.map((t) => t.title).join(", ")}.`);
        });
      }
      if (Array.isArray(s.trips) && s.trips.length) {
        s.trips.forEach((t) => {
          const start = new Date(t.startDate);
          const daysOut = Math.round((start - today) / 86400000);
          if (daysOut >= 0 && daysOut <= 21) {
            const allItems = [...(t.prep || []), ...(t.packing || []), ...(t.departureDay || [])];
            const unchecked = allItems.filter((i) => !i.checked).length;
            lines.push(`Trip "${t.name}" to ${t.destination} in ${daysOut} days — ${unchecked} unchecked items across prep/packing/departure.`);
          }
        });
      }
      return lines.length ? lines.join(" ") : null;
    } catch (e) {
      return null;
    }
  }

